INSERT INTO derive_story_contract (
    run_id, version, status, truth_kernel, character_slots, event_kernel,
    clue_registry, knowledge_ledger, constraint_kernel, source_hash
) VALUES (
    #{p.runId}, #{p.version}, #{p.status},
    #{p.truthKernel}::jsonb, #{p.characterSlots}::jsonb, #{p.eventKernel}::jsonb,
    #{p.clueRegistry}::jsonb, #{p.knowledgeLedger}::jsonb, #{p.constraintKernel}::jsonb,
    #{p.sourceHash}
) RETURNING id
